#!/usr/bin/env bash
# Derives every generated file from config/app.json. Idempotent; safe to run any time.
# Writes ONLY files owned by this project (never anything under src-tauri/gen/).
#   src-tauri/tauri.conf.json                          (name, version, identifier, plugin config, bundle info)
#   src-tauri/Info.ios.plist                           (iOS usage descriptions, merged by the Tauri CLI)
#   plugins/web2app-native/android/src/main/AndroidManifest.xml  (permissions of enabled features, merged by Gradle)
#   src-tauri/splash-logo.png                          (in-page splash logo)
#   src-tauri/capabilities/remote.json                (origins allowed to call the bridge; build.rs regenerates the same content
#                                                      and a Rust unit test checks it equals the runtime policy)
set -euo pipefail
# shellcheck source=lib/common.sh
. "$(dirname "${BASH_SOURCE[0]}")/lib/common.sh"
require_jq

CONF="$W2A_ROOT/src-tauri/tauri.conf.json"
[ -f "$CONF" ] || die "missing $CONF"

# ---- tauri.conf.json --------------------------------------------------------
jq --slurpfile app "$APP_JSON" '
  ($app[0]) as $a
  | .productName = $a.app.name
  | .version = $a.app.version
  | .identifier = $a.app.identifier
  | .bundle.publisher = ($a.app.author.name // "")
  | .bundle.copyright = ($a.app.copyright // "")
  | .bundle.shortDescription = ($a.app.description // "")
  | .bundle.longDescription = ($a.app.description // "")
  | .plugins["web2app-native"].downloads = (if $a.features.downloads == false then false else true end)
  | .plugins["web2app-native"].statusBarColor = ($a.appearance.statusBarColor // null)
  | .plugins["web2app-native"].navigationBarColor = ($a.appearance.navigationBarColor // null)
' "$CONF" | atomic_write "$CONF"
ok "tauri.conf.json updated"

# ---- remote capability: ONLY the configured origins may call the bridge ---------------
jq -S '
  def ent: ascii_downcase | gsub("^\\s+|\\s+$";"");
  def pat($scheme; $wild; $host; $port):
    $scheme + "://" + (if $wild then "*." else "" end) + $host + (if $port == null then "" else ":" + ($port|tostring) end);
  def parse($e): ($e | ent) as $x
    | ($x | startswith("*.")) as $w
    | ($x | ltrimstr("*.")) as $r
    | (if ($r | test(":[0-9]+$")) then ($r | capture("^(?<h>.*):(?<p>[0-9]+)$")) else {h:$r, p:null} end) as $hp
    | {wild:$w, host:($hp.h | sub("\\.+$";"")), port:(if $hp.p == null or $hp.p == "80" or $hp.p == "443" then null else ($hp.p|tonumber) end)};
  (if .security.httpsOnly == false then "http" else "https" end) as $scheme
  | (.site.url | capture("^[a-zA-Z]+://(?<h>[^/:?#]+)(:(?<p>[0-9]+))?")) as $u
  | ($u.h | ascii_downcase | sub("\\.+$";"")) as $host
  | (if $u.p == null or $u.p == "80" or $u.p == "443" then null else ($u.p|tonumber) end) as $port
  | ([{wild:false, host:$host, port:$port}]
     + (if (.site.includeSubdomains == true) and ($host | contains(".")) and ($host | test("^[0-9.]+$") | not) then [{wild:true, host:$host, port:$port}] else [] end)
     + [ (.site.allowedDomains // [])[] | parse(.) ]) as $rules
  | {
      identifier: "remote-site",
      description: "ONLY the configured site origins may call the Web2App bridge (nothing else of Tauri IPC). GENERATED by build.rs from config/app.json - do not edit.",
      local: false,
      remote: { urls: [ $rules[] | pat($scheme; .wild; .host; .port) ] },
      windows: ["main", "popup-*"],
      permissions: ["allow-bridge"]
    }' "$APP_JSON" | atomic_write "$W2A_ROOT/src-tauri/capabilities/remote.json"
ok "remote capability generated"

# ---- Android manifest (plugin-owned, merged by Gradle) --------------------------
MANIFEST="$W2A_ROOT/plugins/web2app-native/android/src/main/AndroidManifest.xml"
f() { jq -r ".features.$1 // false" "$APP_JSON"; }
{
  echo '<?xml version="1.0" encoding="utf-8"?>'
  echo '<!-- GENERATED by scripts/sync-config.sh from config/app.json. Do not edit by hand. -->'
  echo '<manifest xmlns:android="http://schemas.android.com/apk/res/android">'
  echo '    <uses-permission android:name="android.permission.INTERNET" />'
  echo '    <uses-permission android:name="android.permission.ACCESS_NETWORK_STATE" />'
  if [ "$(f camera)" = true ]; then
    echo '    <uses-permission android:name="android.permission.CAMERA" />'
    echo '    <uses-feature android:name="android.hardware.camera" android:required="false" />'
  fi
  if [ "$(f microphone)" = true ]; then
    echo '    <uses-permission android:name="android.permission.RECORD_AUDIO" />'
    echo '    <uses-permission android:name="android.permission.MODIFY_AUDIO_SETTINGS" />'
  fi
  if [ "$(f geolocation)" = true ]; then
    echo '    <uses-permission android:name="android.permission.ACCESS_FINE_LOCATION" />'
    echo '    <uses-permission android:name="android.permission.ACCESS_COARSE_LOCATION" />'
  fi
  if [ "$(f downloads)" = true ]; then
    echo '    <uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE" android:maxSdkVersion="28" />'
  fi
  if [ "$(f notifications)" = true ]; then
    echo '    <uses-permission android:name="android.permission.POST_NOTIFICATIONS" />'
  fi
  echo '</manifest>'
} | atomic_write "$MANIFEST"
ok "Android manifest permissions generated"

# ---- iOS usage descriptions (src-tauri/Info.ios.plist is merged by the Tauri CLI) -----
PLIST="$W2A_ROOT/src-tauri/Info.ios.plist"
NAME="$(jq -r '.app.name' "$APP_JSON")"
xml_escape() { sed -e 's/&/\&amp;/g' -e 's/</\&lt;/g' -e 's/>/\&gt;/g'; }
ENAME="$(printf '%s' "$NAME" | xml_escape)"
{
  echo '<?xml version="1.0" encoding="UTF-8"?>'
  echo '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">'
  echo '<!-- GENERATED by scripts/sync-config.sh from config/app.json. Do not edit by hand. -->'
  echo '<plist version="1.0">'
  echo '<dict>'
  echo '    <key>ITSAppUsesNonExemptEncryption</key><false/>'
  if [ "$(f camera)" = true ] || [ "$(f fileUpload)" = true ]; then
    echo "    <key>NSCameraUsageDescription</key><string>$ENAME needs the camera to take photos and videos for the website.</string>"
  fi
  if [ "$(f fileUpload)" = true ]; then
    echo "    <key>NSPhotoLibraryUsageDescription</key><string>$ENAME needs access to your photos so you can upload them to the website.</string>"
  fi
  if [ "$(f microphone)" = true ]; then
    echo "    <key>NSMicrophoneUsageDescription</key><string>$ENAME needs the microphone for audio features of the website.</string>"
  fi
  if [ "$(f geolocation)" = true ]; then
    echo "    <key>NSLocationWhenInUseUsageDescription</key><string>$ENAME uses your location for location-based features of the website.</string>"
  fi
  echo '</dict>'
  echo '</plist>'
} | atomic_write "$PLIST"
ok "iOS Info.ios.plist generated"

# ---- splash logo ----------------------------------------------------------------
LOGO_SRC="$W2A_ROOT/$(jq -r '.appearance.logoSource // empty' "$APP_JSON")"
LOGO_DST="$W2A_ROOT/src-tauri/splash-logo.png"
if [ -f "$LOGO_SRC" ] && [ "$(image_kind "$LOGO_SRC")" = png ]; then
  if command -v convert >/dev/null 2>&1; then
    convert "$LOGO_SRC" -resize '256x256>' "$LOGO_DST" 2>/dev/null || cp "$LOGO_SRC" "$LOGO_DST"
  else
    cp "$LOGO_SRC" "$LOGO_DST"
  fi
  ok "splash logo updated"
else
  warn "no PNG splash logo found at ${LOGO_SRC#"$W2A_ROOT"/}; the splash will show only the background color"
  convert -size 1x1 xc:none "$LOGO_DST" 2>/dev/null || true
fi
